+      int num_quad = 1;
+      for (int ndim = 1; ndim <= 3; ++ndim) {
+        num_quad *= order + 1;
+        check_quad_roundtrip(gpython_basis_new(types[type], ndim, order), num_quad);
+      }
+    }
+  }
+}
+
+void
+test_gpython_quad_hybrid()
+{
+  for (int cdim = 1; cdim <= 3; ++cdim) {
+    int num_quad = 1 << cdim;
+    for (int vdim = 1; vdim <= 3; ++vdim) {
